def bekkers_cdf(x, a, m, d):
    def integrand(t):
        return bekkers(t, a, m, d)
    cdf, _ = integrate.quad(integrand, range_start, x)
    total, _ = integrate.quad(integrand, range_start, range_end)
    return cdf / total if total != 0 else 0.0

result = stats.kstest(sample_data, bekkers_cdf, args=(estimated_a, estimated_m, estimated_d))

def cdf(x, a, m, d):
    return integrate.quad(lambda t: bekkers(t, a, m, d), range_start, x)[0] / integrate.quad(lambda t: bekkers(t, a, m, d), range_start, range_end)[0]

result = stats.kstest(sample_data, cdf, args=(estimated_a, estimated_m, estimated_d))
